pub fn open(path: &str) -> rusqlite::Result<Connection> {
    let conn = Connection::open(path)?;
    conn.execute_batch(
        "PRAGMA journal_mode = WAL;
         PRAGMA foreign_keys = ON;
         PRAGMA busy_timeout = 5000;",
    )?;
    migrate(&conn)?;
    Ok(conn)
}

/// Schema migrations, tracked with `PRAGMA user_version`. Append new steps; never edit old ones.
fn migrate(conn: &Connection) -> rusqlite::Result<()> {
    let migrations: &[&str] = &[
        // 1: quizzes, questions, options
        "CREATE TABLE quizzes (
            id INTEGER PRIMARY KEY,
            title TEXT NOT NULL,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
         );
         CREATE TABLE questions (
            id INTEGER PRIMARY KEY,
            quiz_id INTEGER NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,
            position INTEGER NOT NULL,
            body TEXT NOT NULL,
            active INTEGER NOT NULL DEFAULT 1
         );
         CREATE INDEX questions_quiz ON questions(quiz_id, position);
         CREATE TABLE options (
            id INTEGER PRIMARY KEY,
            question_id INTEGER NOT NULL REFERENCES questions(id) ON DELETE CASCADE,
            position INTEGER NOT NULL,
            text TEXT NOT NULL,
            correct INTEGER NOT NULL DEFAULT 0
         );
         CREATE INDEX options_question ON options(question_id, position);",
        // 2: live games, players, answers
        "CREATE TABLE games (
            id INTEGER PRIMARY KEY,
            quiz_id INTEGER NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,
            code TEXT NOT NULL UNIQUE,
            state TEXT NOT NULL DEFAULT 'lobby',
            question_id INTEGER REFERENCES questions(id) ON DELETE SET NULL,
            question_num INTEGER NOT NULL DEFAULT 0,
            seq INTEGER NOT NULL DEFAULT 0,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            started_at TEXT,
            ended_at TEXT
         );
         CREATE INDEX games_quiz ON games(quiz_id);
         CREATE TABLE game_questions (
            game_id INTEGER NOT NULL REFERENCES games(id) ON DELETE CASCADE,
            question_id INTEGER NOT NULL REFERENCES questions(id) ON DELETE CASCADE,
            num INTEGER NOT NULL,
            opened_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now')),
            closed_at TEXT,
            PRIMARY KEY (game_id, question_id)
         );
         CREATE TABLE players (
            id INTEGER PRIMARY KEY,
            game_id INTEGER NOT NULL REFERENCES games(id) ON DELETE CASCADE,
            token TEXT NOT NULL UNIQUE,
            name TEXT NOT NULL,
            joined_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
         );
         CREATE INDEX players_game ON players(game_id);
         CREATE TABLE answers (
            game_id INTEGER NOT NULL REFERENCES games(id) ON DELETE CASCADE,
            question_id INTEGER NOT NULL REFERENCES questions(id) ON DELETE CASCADE,
            player_id INTEGER NOT NULL REFERENCES players(id) ON DELETE CASCADE,
            option_id INTEGER NOT NULL REFERENCES options(id) ON DELETE CASCADE,
            seq INTEGER NOT NULL DEFAULT 0,
            answered_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%d %H:%M:%f', 'now')),
            PRIMARY KEY (player_id, question_id)
         );
         CREATE INDEX answers_game_question ON answers(game_id, question_id);",
    ];
    let version: usize = conn.query_row("PRAGMA user_version", [], |r| r.get::<_, i64>(0))? as usize;
    for (i, sql) in migrations.iter().enumerate().skip(version) {
        conn.execute_batch(&format!(
            "BEGIN; {sql}; PRAGMA user_version = {}; COMMIT;",
            i + 1
        ))?;
    }
    Ok(())
}

pub struct QuizSummary {
    pub quiz: Quiz,
    pub questions: i64,
    pub active: i64,
}

pub fn list_quizzes(conn: &Connection) -> rusqlite::Result<Vec<QuizSummary>> {
    let mut st = conn.prepare(
        "SELECT q.id, q.title,
                (SELECT COUNT(*) FROM questions WHERE quiz_id = q.id),
                (SELECT COUNT(*) FROM questions WHERE quiz_id = q.id AND active = 1)
         FROM quizzes q ORDER BY q.id DESC",
    )?;
    st.query_map([], |r| {
        Ok(QuizSummary {
            quiz: Quiz { id: r.get(0)?, title: r.get(1)? },
            questions: r.get(2)?,
            active: r.get(3)?,
        })
    })?
    .collect()
}

