/// Uniform random number in `0..n` (n > 0), from /dev/urandom (rejection sampling, no bias).
fn random_below(n: usize) -> usize {
    let n = n as u64;
    let zone = u64::MAX - u64::MAX % n;
    loop {
        let v = u64::from_le_bytes(random_bytes::<8>());
        if v < zone {
            return (v % n) as usize;
        }
    }
}

